package app.loki.anithere.dialogs

import androidx.compose.runtime.Composable
import kotlinx.serialization.json.JsonObject

// Generated by egui2compose: the dialogs translated from the desktop front end, for the app to
// open from wherever each belongs (a group's launcher, a menu entry, an engine request).

class TranslatedDialog(val title: String, val source: String, val show: @Composable (onRun: (String, JsonObject) -> Unit, onDismiss: () -> Unit) -> Unit)

val TRANSLATED_DIALOGS: List<TranslatedDialog> = listOf(
    TranslatedDialog("Preferences", "dialogs.rs") { onRun, onDismiss -> PreferencesDialog(onRun, onDismiss) },
    TranslatedDialog("Aids dialog guides window", "aids_dialog.rs") { onRun, onDismiss -> AidsDialogGuidesWindowDialog(onRun, onDismiss) },
    TranslatedDialog("Aids dialog grid window", "aids_dialog.rs") { onRun, onDismiss -> AidsDialogGridWindowDialog(onRun, onDismiss) },
    TranslatedDialog("Aids dialog spacing field", "aids_dialog.rs") { onRun, onDismiss -> AidsDialogSpacingFieldDialog(onRun, onDismiss) },
    TranslatedDialog("Confirm modal", "dialogs.rs") { onRun, onDismiss -> ConfirmModalDialog(onRun, onDismiss) },
    TranslatedDialog("Palette", "dialogs.rs") { onRun, onDismiss -> PaletteDialog(onRun, onDismiss) },
    TranslatedDialog("Font picker", "dialogs.rs") { onRun, onDismiss -> FontPickerDialog(onRun, onDismiss) },
    TranslatedDialog("Shortcut sheet", "dialogs.rs") { onRun, onDismiss -> ShortcutSheetDialog(onRun, onDismiss) },
)
